from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen=set(); frames=[]
    for r in range(h):
        for c in range(w):
            col=grid[r][c]
            if not col or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); comp=[]
            while q:
                rr,cc=q.pop(); comp.append((rr,cc))
                for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0<=nr<h and 0<=nc<w and (nr,nc) not in seen and grid[nr][nc]==col:
                        seen.add((nr,nc)); q.append((nr,nc))
            r0=min(a for a,b in comp); r1=max(a for a,b in comp)
            c0=min(b for a,b in comp); c1=max(b for a,b in comp)
            if r1-r0>=2 and c1-c0>=2:
                ring={(rr,cc) for rr in range(r0,r1+1) for cc in range(c0,c1+1)
                      if rr in (r0,r1) or cc in (c0,c1)}
                if set(comp)==ring:
                    frames.append((r0,r1,c0,c1,col,ring))
    frame_cells=set().union(*(f[5] for f in frames)) if frames else set()
    counts=Counter(grid[r][c] for r in range(h) for c in range(w) if grid[r][c] and (r,c) not in frame_cells)
    # Use unique colors and choose the closest count to each frame's required checker cells.
    fills={}
    available=set(counts)
    for r0,r1,c0,c1,col,ring in sorted(frames, key=lambda f: ((f[1]-f[0]-1)*(f[3]-f[2]-1)+1)//2):
        nrows=r1-r0-1; ncols=c1-c0-1
        need=(nrows*ncols+1)//2
        if available:
            fc=min(available,key=lambda x:(abs(counts[x]-need), x))
            fills[(r0,r1,c0,c1)]=fc; available.remove(fc)
    out=[[0]*w for _ in range(h)]
    for r0,r1,c0,c1,col,ring in frames:
        for r,c in ring: out[r][c]=col
        fc=fills.get((r0,r1,c0,c1))
        if fc is not None:
            for r in range(r0+1,r1):
                for c in range(c0+1,c1):
                    if (r-r0-1+c-c0-1)%2==0: out[r][c]=fc
    return out

